  public static List<TrainStage> Ordered(TransmissionTrain t){var result=new List<TrainStage>();string id=null;while(result.Count<t.Stages.Count){var next=t.Stages.Where(n=>n.Parent==id&&!result.Contains(n)).ToArray();if(next.Length!=1)throw new Exception("Общий корпус: нужна одна цепочка без разветвлений и циклов.");result.Add(next[0]);id=next[0].Id;}return result;}
  public static void Validate(TransmissionTrain t){if(!Enabled(t))return;var h=t.SharedHousing;Range(h.Wall,2,30,"Минимальная стенка");Range(h.Partition,3,40,"Перегородка");Range(h.Clearance,.05,2,"Зазор");Range(h.BoltDiameter,2,12,"Диаметр шпильки");if(h.Bolts<3||h.Bolts>12)throw new Exception("Общий корпус: число шпилек 3–12.");if(h.Shape!="Round"&&h.Shape!="Square")throw new Exception("Общий корпус: выберите круг или квадрат.");if(h.Joint!="CommonShaft"&&h.Joint!="D"&&h.Joint!="Spline")throw new Exception("Общий корпус: неизвестное соединение ступеней.");if(!h.SplitPerStage)throw new Exception("Общий корпус: для этой версии включите деление на модули.");if(t.Stages.Count<2||t.Stages.Count>4)throw new Exception("В общем корпусе допускаются 2–4 ступени.");foreach(var n in t.Stages){if(n.SecondParent!=null||n.PowerShare!=1)throw new Exception(n.Name+": общий корпус требует одного входа без деления мощности.");if(n.Parameters.Kind!=0&&n.Parameters.Kind!=3&&n.Parameters.Kind!=4)throw new Exception(n.Name+": эта ступень не ставится в общий корпус; выберите соосную передачу.");if(n.Parameters.Kind==0&&n.Parameters.RingOutput)throw new Exception(n.Name+": для общего корпуса выключите «Выход через кольцо» в параметрах ступени.");if(n.Parameters.Kind==0&&n.Parameters.CycloidLayout!=0)throw new Exception(n.Name+": выберите стандартную циклоидальную схему.");}
   var chain=Ordered(t);for(int i=1;i<chain.Count;i++){double a=chain[i-1].Parameters.OutputShaft,b=chain[i].Parameters.Shaft;if(!MechanismCad.Finite(a)||!MechanismCad.Finite(b)||Math.Abs(a-b)>1e-6)throw new Exception(chain[i-1].Name+" → "+chain[i].Name+": выходной вал Ø"+Engine.F(a)+" мм не совпадает со входом Ø"+Engine.F(b)+" мм. Задайте одинаковые диаметры или нажмите «Согласовать валы» на вкладке «Общий корпус».");}
  }
